import { readdirSync, writeFileSync } from 'node:fs';

const directory = new URL('../src/i18n/sections/', import.meta.url);
const sections = readdirSync(directory)
  .filter((file) => file !== 'index.ts' && file.endsWith('.ts'))
  .sort()
  .map((file) => {
    const slug = file.slice(0, -3);
    const name = slug.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());
    return { slug, name };
  });

writeFileSync(
  new URL('index.ts', directory),
  [
    '// Generated by npm run i18n:generate-index.',
    ...sections.map(({ slug, name }) => `import { ${name} } from './${slug}';`),
    '',
    'export const sections = [',
    ...sections.map(({ name }) => `  ${name},`),
    '] as const;',
    '',
  ].join('\n'),
);
